script:
class Component extends DCLogic {
  constructor(props) { super(props); this.state = { tab: 'over', netF: 'all', clF: 'all', open: {}, actOpen: false, lvlOpen: false, m: '', invited: [], staff: [{ id: 's1', name: 'Анна Ким', mail: 'a.kim@peragov.example' }],
    iName: '', iMail: '', iErr: false, iDone: false, sName: '', sMail: '', sErr: false, msgTo: '', mText: '', mErr: false }; }

  _y(e) { try { const m = document.querySelector('main.kab__main'); return Math.round(e.currentTarget.getBoundingClientRect().top - m.getBoundingClientRect().top); } catch (x) { return 120; } }
  say(msg, e) { const y = this._y(e); this.setState({ toast: msg, toastY: Math.max(8, y + ((e && e.currentTarget && e.currentTarget.offsetHeight) || 40) + 8) }); clearTimeout(this._tt); this._tt = setTimeout(() => this.setState({ toast: '' }), 3800); }
  openM(name, e, extra) { const y = this._y(e); this.setState(Object.assign({ m: name, mTop: Math.max(16, y - 40) }, extra || {})); }
  closeM() { this.setState({ m: '' }); }
  baseVals() {
    const S = this.state;
    return { toastOn: !!S.toast, toast: S.toast || '', toastStyle: 'top:' + (S.toastY || 80) + 'px;width:max-content;max-width:min(420px,calc(100% - 32px))', mOn: !!S.m, ovlStyle: 'padding-top:' + (S.mTop || 24) + 'px',
      closeOvl: (e) => { if (e.target === e.currentTarget) this.closeM(); }, closeBtn: () => this.closeM(),
      helpOpen: (e) => this.openM('help', e), m_help: S.m === 'help' };
  }

  renderVals() {
    const S = this.state, ok = (v) => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v.trim());
    const tog = (id) => () => this.setState({ open: Object.assign({}, S.open, { [id]: !S.open[id] }) });
    const mk = (r) => Object.assign({ open: !!S.open[r.id], pick: tog(r.id), msg: (e) => this.openM('msg', e, { msgTo: r.name, mText: '', mErr: false }) }, r);
    const T = [['over', 'Обзор'], ['net', 'Моя сеть'], ['cl', 'Клиенты сети'], ['staff', 'Сотрудники'], ['com', 'Коммьюнити']].filter((t) => !(HB.isNovice() && t[0] === 'over'));
    const tabs = T.map(([k, t]) => ({ t, sel: S.tab === k, pick: () => this.setState({ tab: k, open: {} }) }));
    const P = (HB.isNovice() ? [] : [
      { id: 'p1', name: 'Марат Сулейманов', act: 'Суперактивный', badge: 'badge--ok', sub: 'Уровень 1. Последняя активность 5 ноября', det: 'marat.s@mail.example. 3 клиента, 1 заявка.' },
      { id: 'p2', name: 'Елена Воронцова', act: 'Активный', badge: 'badge--ok', sub: 'Уровень 1. Последняя активность 3 ноября', det: 'e.vorontsova@mail.example. 2 клиента, заявок пока нет.' },
      { id: 'p3', name: 'Роман Гусев', act: 'Средний', badge: 'badge--muted', sub: 'Уровень 1. Последняя активность 22 сентября', det: 'r.gusev@mail.example. 1 клиент. Давно не было движения, стоит написать.' }]).concat(S.invited.map((x) => ({ id: x.id, name: x.name, act: 'Ждёт регистрации', badge: 'badge--muted', sub: 'Уровень 1. Приглашение отправлено сегодня', det: x.mail + '. Как только человек зарегистрируется, он встанет в Вашу сеть.' })));
    const NF = ['Все', 'Суперактивные', 'Активные', 'Средние'], MAP = { 'Суперактивные': 'Суперактивный', 'Активные': 'Активный', 'Средние': 'Средний' };
    const netPills = NF.map((t) => ({ t, n: t === 'Все' ? P.length : P.filter((p) => p.act === MAP[t]).length, on: S.netF === t || (t === 'Все' && S.netF === 'all'), pick: () => this.setState({ netF: t, open: {} }) }));
    const netRows = P.filter((p) => S.netF === 'all' || S.netF === 'Все' || p.act === MAP[S.netF]).map((p) => mk(Object.assign({}, p, { tag: p.act })));
    const C = HB.isNovice() ? [] : [
      { id: 'c1', name: 'Роман Гусев', st: 'В процессе', badge: 'badge--muted', sub: 'Линия 1. Подбор без движения 45 дней', det: 'Передан 22 сентября 2026. Менеджер ещё не назначен.' },
      { id: 'c2', name: 'Елена Воронцова', st: 'Связались', badge: 'badge--muted', sub: 'Линия 1. Связались, движения нет 25 дней', det: 'Передан 12 октября 2026. Менеджер ещё не назначен.' },
      { id: 'c3', name: 'Марат Сулейманов', st: 'Внесён депозит', badge: 'badge--ok', sub: 'Линия 1. Дошёл до оплаты', det: 'Передан 3 ноября 2026. Менеджер ещё не назначен.' },
      { id: 'c4', name: 'Внук Первый', st: 'Новый', badge: 'badge--muted', sub: 'Линия 2. Никто не принял 5 дней', det: 'Передан 1 ноября 2026. Менеджер ещё не назначен.' }];
    const CF = ['Все', 'Новый', 'Связались', 'В процессе', 'Внесён депозит'];
    const clPills = CF.map((t) => ({ t, n: t === 'Все' ? C.length : C.filter((c) => c.st === t).length, on: S.clF === t || (t === 'Все' && S.clF === 'all'), pick: () => this.setState({ clF: t, open: {} }) }));
    const clRows = C.filter((c) => S.clF === 'all' || S.clF === 'Все' || c.st === S.clF).map((c) => mk(Object.assign({}, c, { tag: c.st })));
    const staffRows = S.staff.map((x) => mk({ id: x.id, name: x.name, tag: 'Сотрудник', badge: 'badge--muted', sub: x.mail, det: 'Работает в Вашем кабинете. Деньги и договор остаются за Вами.', del: (e) => { this.setState({ staff: S.staff.filter((y) => y.id !== x.id), open: {} }); this.say('Сотрудник убран', e); } }));
    const comRows = [['Сделочник Глеб', 'Россия. 2 заявки'], ['Супер Активный', 'Россия. 1 заявка'], ['Nord Estate', 'Россия, Санкт-Петербург. 0 заявок'], ['Housebook QA', 'ОАЭ, Дубай. 0 заявок']].map(([n, s], i) => mk({ id: 'k' + i, name: (i + 2) + '. ' + n, tag: 'Партнёр', badge: 'badge--muted', sub: s, det: 'Можно написать напрямую: обсудить клиента или совместную сделку.' }));
    const e1 = S.iErr && !S.iName.trim() ? 'is-err' : '', e2 = S.iErr && !ok(S.iMail) ? 'is-err' : '', e3 = S.sErr && !S.sName.trim() ? 'is-err' : '', e4 = S.sErr && !ok(S.sMail) ? 'is-err' : '';
    return Object.assign(this.baseVals(), { tabs, tOver: S.tab === 'over', tNet: S.tab === 'net', tCl: S.tab === 'cl', tStaff: S.tab === 'staff', tCom: S.tab === 'com',
      netN: (HB.isNovice() ? 0 : 10) + S.invited.length, netShown: netRows.length, netAll: (e) => this.say('В кабинете откроется полный список', e), actOpen: S.actOpen, actToggle: () => this.setState({ actOpen: !S.actOpen }), lvlOpen: S.lvlOpen, lvlToggle: () => this.setState({ lvlOpen: !S.lvlOpen }),
      netPills, netRows, netEmpty: netRows.length === 0, clPills, clRows, staffRows, comRows,
      invOpen: (e) => this.openM('inv', e, { iDone: false, iErr: false, iName: '', iMail: '' }), staffOpen: (e) => this.openM('staff', e, { sErr: false, sName: '', sMail: '' }),
      m_inv: S.m === 'inv', m_staff: S.m === 'staff', m_msg: S.m === 'msg', iForm: !S.iDone, iDone: S.iDone,
      iName: S.iName, iMail: S.iMail, iSetName: (e) => this.setState({ iName: e.target.value, iErr: false }), iSetMail: (e) => this.setState({ iMail: e.target.value, iErr: false }),
      iNameErr: e1, iNameErr_e: e1 ? 'Напишите имя' : '', iMailErr: e2, iMailErr_e: e2 ? 'Проверьте почту: нужен адрес вида name@example.com' : '',
      iSend: (e) => { if (e && e.preventDefault) e.preventDefault(); if (!S.iName.trim() || !ok(S.iMail)) { this.setState({ iErr: true }); return; } this.setState({ iDone: true, invited: S.invited.concat([{ id: 'n' + (S.invited.length + 1), name: S.iName.trim(), mail: S.iMail.trim(), ts: Date.now() }]) }); },
      iToNet: () => this.setState({ m: '', tab: 'net', netF: 'all' }),
      sName: S.sName, sMail: S.sMail, sSetName: (e) => this.setState({ sName: e.target.value, sErr: false }), sSetMail: (e) => this.setState({ sMail: e.target.value, sErr: false }),
      sNameErr: e3, sNameErr_e: e3 ? 'Напишите имя' : '', sMailErr: e4, sMailErr_e: e4 ? 'Проверьте почту' : '',
      sSend: (e) => { if (e && e.preventDefault) e.preventDefault(); if (!S.sName.trim() || !ok(S.sMail)) { this.setState({ sErr: true }); return; } this.setState({ m: '', tab: 'staff', staff: S.staff.concat([{ id: 's' + (S.staff.length + 9), name: S.sName.trim(), mail: S.sMail.trim() }]) }); this.say('Сотрудник добавлен', e); },
      msgTo: S.msgTo, mText: S.mText, mSet: (e) => this.setState({ mText: e.target.value, mErr: false }), mErr: S.mErr && !S.mText.trim() ? 'is-err' : '', mErr_e: S.mErr && !S.mText.trim() ? 'Напишите сообщение' : '',
      mSend: (e) => { if (e && e.preventDefault) e.preventDefault(); if (!S.mText.trim()) { this.setState({ mErr: true }); return; } this.setState({ m: '' }); this.say('Сообщение отправлено', e); } });
  }
}

Component = (function (Base) { return class extends Base {
  constructor(props) { super(props); if (HB.isNovice()) { this.state.staff = []; this.state.tab = 'net'; } }
  renderVals() { const v = super.renderVals(); const S = this.state, set = (o) => this.setState(o); v.netBlank = v.netN === 0; v.hasNet = v.netN > 0; v.clBlank = HB.isNovice(); v.staffBlank = S.staff.length === 0;
    if (v.netBlank) v.netPills = []; if (v.clBlank) { v.clPills = []; } if (HB.isNovice()) v.comRows = []; return v; }
}; })(Component);
